css:
:root {
  --bg: #ffffff;
  --surface: #fafafa;
  --border: #111111;
  --text: #111111;
  --text-medium: #333333;
  --text-muted: #555555;
  --text-ghost: #999999;
}
:root.dark {
  --bg: #000000;
  --surface: #101010;
  --border: #eeeeee;
  --text: #eeeeee;
  --text-medium: #cccccc;
  --text-muted: #aaaaaa;
  --text-ghost: #666666;
}
.card-tile { border: 2px solid var(--border); border-radius: 0; box-shadow: 4px 4px 0 var(--border); }
.card-tile:hover { box-shadow: 6px 6px 0 var(--border); }
.card-tag { background: var(--text); color: var(--bg); border-radius: 0; }
.header { border-bottom: 3px solid var(--border); }
